	setupChoice, err = promptBootstrapSetupChoice(w, cwd, githubReady)
	if err != nil {
		return nil, err
	}
	if setupChoice == bootstrapSetupDecline {
		return nil, errBootstrapDeclined
	}
} else {
	proceed, confirmErr := confirmInitRepo(w, cwd, opts)
	if confirmErr != nil {
		return nil, confirmErr
	}
	if !proceed {
		return nil, errBootstrapDeclined
	}
}

